${CLICKHOUSE_CLIENT} --query "
    TRUNCATE TABLE hmcd;
    ALTER TABLE hmcd ATTACH PARTITION tuple() FROM hmcd_src;
    OPTIMIZE TABLE hmcd FINAL;
"

${CLICKHOUSE_CLIENT} --query "
    TRUNCATE TABLE hmcd_replacing;
